<?php require_once 'includes/functions.php';require_login();$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=post('name');$email=strtolower(post('email'));if(strlen($name)<2)$errors[]='Enter your name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(!$errors){try{$s=db()->prepare('UPDATE users SET name=?,email=? WHERE id=?');$s->execute([$name,$email,user()['id']]);$_SESSION['user']['name']=$name;$_SESSION['user']['email']=$email;flash('success','Profile updated.');redirect('profile.php');}catch(PDOException $e){$errors[]='Email is already used.';}}}
$s=db()->prepare('SELECT a.id,a.score,a.total_questions,a.percentage,a.completed_at,q.title FROM attempts a JOIN quizzes q ON q.id=a.quiz_id WHERE a.user_id=? ORDER BY a.completed_at DESC');$s->execute([user()['id']]);$history=$s->fetchAll();$pageTitle='Profile';require 'includes/header.php';?>
<div class="split"><form class="form-card wide" method="post"><h1>Student Information</h1><?php foreach($errors as $x):?><p class="error"><?=e($x)?></p><?php endforeach;?><?=csrf_field()?><label>Name</label><input name="name" value="<?=e(user()['name'])?>" required><label>Email</label><input type="email" name="email" value="<?=e(user()['email'])?>" required><br><br><button>Save Changes</button></form><div class="card"><h2>Account</h2><p><strong>Role:</strong> Student</p><p><strong>Total attempts:</strong> <?=count($history)?></p></div></div>
<h2>Quiz History</h2><div class="table-wrap"><table><tr><th>Quiz</th><th>Score</th><th>Percentage</th><th>Date</th><th></th></tr><?php foreach($history as $r):?><tr><td><?=e($r['title'])?></td><td><?=$r['score']?> / <?=$r['total_questions']?></td><td><?=$r['percentage']?>%</td><td><?=date('d M Y H:i',strtotime($r['completed_at']))?></td><td><a href="result.php?id=<?=$r['id']?>">Review</a></td></tr><?php endforeach;?></table><?php if(!$history):?><p>No quiz history yet.</p><?php endif;?></div>
<?php require 'includes/footer.php';?>
